func (this *Coincheck) ParseTransaction(transaction any, optionalArgs ...any) any {
	//
	// fetchDeposits
	//
	// {
	//       "id": 2,
	//       "amount": "0.05",
	//       "currency": "BTC",
	//       "address": "13PhzoK8me3u5nHzzFD85qT9RqEWR9M4Ty",
	//       "status": "confirmed",
	//       "confirmed_at": "2015-06-13T08:29:18.000Z",
	//       "created_at": "2015-06-13T08:22:18.000Z"
	//  }
	//
	// fetchWithdrawals
	//
	//  {
	//       "id": 398,
	//       "status": "finished",
	//       "amount": "242742.0",
	//       "currency": "JPY",
	//       "created_at": "2014-12-04T15:00:00.000Z",
	//       "bank_account_id": 243,
	//       "fee": "400.0",
	//       "is_fast": true
	//  }
	//
	currency := GetArg(optionalArgs, 0, nil)
	_ = currency
	var id any = this.SafeString(transaction, "id")
	var timestamp any = this.Parse8601(this.SafeString(transaction, "created_at"))
	var address any = this.SafeString(transaction, "address")
	var amount any = this.SafeNumber(transaction, "amount")
	var currencyId any = this.SafeString(transaction, "currency")
	var code any = this.SafeCurrencyCode(currencyId, currency)
	var status any = this.ParseTransactionStatus(this.SafeString(transaction, "status"))
	var updated any = this.Parse8601(this.SafeString(transaction, "confirmed_at"))
	var fee any = nil
	var feeCost any = this.SafeNumber(transaction, "fee")
	if IsTrue(!IsEqual(feeCost, nil)) {
		fee = map[string]any{
			"cost":     feeCost,
			"currency": code,
		}
	}
	return map[string]any{
		"info":        transaction,
		"id":          id,
		"txid":        nil,
		"timestamp":   timestamp,
		"datetime":    this.Iso8601(timestamp),
		"network":     nil,
		"address":     address,
		"addressTo":   address,
		"addressFrom": nil,
		"tag":         nil,
		"tagTo":       nil,
		"tagFrom":     nil,
		"type":        nil,
		"amount":      amount,
		"currency":    code,
		"status":      status,
		"updated":     updated,
		"comment":     nil,
		"internal":    nil,
		"fee":         fee,
	}
}
